   174→/// Verify if the KZG proofs are correct.
   175→pub fn verify_kzg_proofs<P: Preset>(
   176→    data_column_sidecar: &DataColumnSidecar<P>,
   177→    backend: KzgBackend,
   178→    metrics: Option<&Arc<Metrics>>,
   179→) -> Result<bool> {
   180→    let _timer = metrics.as_ref().map(|metrics| {
   181→        metrics
   182→            .data_column_sidecar_kzg_verification_batch
   183→            .start_timer()
   184→    });
   185→
   186→    let DataColumnSidecar {
   187→        index,
   188→        column,
   189→        kzg_commitments,
   190→        kzg_proofs,
   191→        ..
   192→    } = data_column_sidecar;
   193→
   194→    let cell_indices: Vec<u64> = vec![*index; column.len()];
   195→
   196→    verify_cell_kzg_proof_batch::<P>(kzg_commitments, cell_indices, column, kzg_proofs, backend)
   197→}
